components.css:
.ds-btn-primary {
  display: inline-flex; align-items: center; justify-content: center; gap: .35rem;
  padding: .45rem .75rem;
  border: 1px solid transparent; border-radius: 6px;
  background: var(--accent, #4f8cf7); color: var(--accent-contrast, #07121f);
  font: 500 .82rem/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  white-space: nowrap; cursor: pointer;
  transition: background 120ms ease;
}
.ds-btn-primary:hover { background: var(--accent-strong, #6ba1ff); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: .5; cursor: not-allowed; }

.ds-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .35rem;
  padding: .45rem .75rem;
  border: 1px solid var(--border, #24303f); border-radius: 6px;
  background: var(--bg-elevated, #151d28); color: var(--text, #e6edf3);
  font: 500 .82rem/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  white-space: nowrap; cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease;
}
.ds-btn:hover { background: var(--bg-hover, #1b2532); border-color: var(--border-strong, #33455c); }
.ds-btn:focus-visible { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }

.ds-field { display: flex; flex-direction: column; gap: .3rem; font: 400 14px/1.5 system-ui, sans-serif; }
.ds-field__label { font-size: .76rem; font-weight: 550; color: var(--text-muted, #95a3b4); }
.ds-input {
  width: 100%; min-width: 0;
  padding: .5rem .65rem;
  border: 1px solid var(--border, #24303f); border-radius: 6px;
  background: var(--bg-input, #0d141c); color: var(--text, #e6edf3);
  font: inherit;
}
.ds-input::placeholder { color: var(--text-faint, #7d8fa3); }
.ds-input:focus-visible { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }

.ds-nav { display: flex; flex-direction: column; gap: 2px; width: 240px; }
.ds-nav__item {
  display: flex; align-items: center; gap: .55rem; width: 100%;
  padding: .45rem .55rem;
  border: 0; border-radius: 6px; background: transparent;
  color: var(--text-muted, #95a3b4); text-align: left; cursor: pointer;
  font: 400 14px/1.5 system-ui, sans-serif;
}
.ds-nav__item:hover { background: var(--bg-hover, #1b2532); color: var(--text, #e6edf3); }
.ds-nav__item--active {
  background: var(--bg-active, #1f2c3d); color: var(--text, #e6edf3);
  box-shadow: inset 2px 0 0 var(--accent, #4f8cf7);
}
.ds-nav__item:focus-visible { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }
.ds-nav__count {
  margin-left: auto; min-width: 1.4rem; padding: 0 4px; border-radius: 999px;
  background: var(--bg-elevated, #151d28); color: var(--text-faint, #7d8fa3);
  font-size: .7rem; text-align: center;
}

.ds-row {
  display: flex; gap: .6rem; width: 100%; padding: .55rem; text-align: left;
  border: 1px solid transparent; border-radius: 10px; background: transparent;
  color: var(--text, #e6edf3); font: 400 14px/1.5 system-ui, sans-serif; cursor: pointer;
}
.ds-row:hover { background: var(--bg-hover, #1b2532); }
.ds-row--active { background: var(--bg-active, #1f2c3d); border-color: var(--border-strong, #33455c); }
.ds-row:focus-visible { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }
.ds-row__avatar {
  display: grid; place-items: center; flex: 0 0 30px; width: 30px; height: 30px;
  border-radius: 9px; background: var(--accent-soft, rgba(79, 140, 247, 0.14)); color: var(--accent-strong, #6ba1ff);
  font-size: .9rem; font-weight: 650;
}
.ds-row__body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.ds-row__title { font-weight: 550; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-row__meta { font-size: .76rem; color: var(--text-muted, #95a3b4); }
.ds-row__chips { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 2px; }
.ds-chip {
  display: inline-flex; align-items: center; gap: .3rem; padding: 2px 8px;
  border: 1px solid var(--border, #24303f); border-radius: 999px;
  background: var(--bg-elevated, #151d28); color: var(--text-muted, #95a3b4); font-size: .74rem;
}

.ds-card {
  max-width: 420px; padding: 1rem 1.1rem;
  border: 1px solid var(--border, #24303f); border-radius: 10px;
  background: var(--bg-panel, #111821);
  box-shadow: 0 1px 0 rgba(255,255,255,.03);
  color: var(--text, #e6edf3); font: 400 14px/1.5 system-ui, sans-serif;
}
.ds-card__title {
  margin: 0 0 .6rem; font-size: .8rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: .06em; color: var(--text-muted, #95a3b4);
}
.ds-card__text { margin: 0; font-size: .85rem; color: var(--text-muted, #95a3b4); }

.ds-strength { display: flex; align-items: center; gap: .6rem; max-width: 360px; font: 400 14px/1.5 system-ui, sans-serif; }
.ds-strength__track { display: flex; gap: 3px; flex: 1; }
.ds-strength__cell { flex: 1; height: 4px; border-radius: 999px; background: var(--bg-elevated, #151d28); }
.ds-strength__cell.is-filled { background: var(--warn, #e0a63c); }
.ds-strength__label { font-size: .74rem; color: var(--text-muted, #95a3b4); white-space: nowrap; }

.ds-switch { display: inline-flex; align-items: center; gap: .45rem; cursor: pointer; font: 400 .78rem/1.5 system-ui, sans-serif; color: var(--text-muted, #95a3b4); }
.ds-switch input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.ds-switch__track {
  position: relative; display: inline-block; width: 34px; height: 18px;
  border-radius: 999px; background: var(--bg-elevated, #151d28); border: 1px solid var(--border-strong, #33455c);
  transition: background 120ms ease;
}
.ds-switch__thumb {
  position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%;
  background: var(--text-faint, #7d8fa3);
  transition: transform 120ms ease, background 120ms ease;
}
.ds-switch input:checked + .ds-switch__track {
  background: var(--accent-soft, rgba(79, 140, 247, 0.14));
  border-color: color-mix(in srgb, var(--accent, #4f8cf7) 55%, transparent);
}
.ds-switch input:checked + .ds-switch__track .ds-switch__thumb {
  transform: translateX(16px); background: var(--accent-strong, #6ba1ff);
}
.ds-switch input:focus-visible + .ds-switch__track { outline: 2px solid var(--accent, #4f8cf7); outline-offset: 2px; }
